interface Prepared {schema_version:2;member_id:string;locale:TopicLocale;names_digest:string;boot_id:string;game_rev:number;round_id:string;conversation_revision:number;epoch:number;safety:TopicSafetyState;view:TopicConversationView;expires_at:number}
interface SelfActionsContext {g:TopicGameRow|null;r:{row:TopicRoundRow;data:TopicRoundData}|null;member:boolean;host:boolean;role:string|null|undefined;ordinary:boolean;l:Loaded|null;conv:ConversationLoaded|null;presence:((()=>void)&{deadline:number})|null}
