const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
function requestId(id:unknown):asserts id is string {requireThat(typeof id==='string'&&uuid.test(id),'INVALID_REQUEST',400);}
function exact(input:unknown,required:readonly string[],optional:readonly string[]=[]):asserts input is Record<string,unknown> {requireThat(input!==null&&typeof input==='object'&&!Array.isArray(input)&&required.every(k=>Object.hasOwn(input,k))&&Object.keys(input).every(k=>[...required,...optional].includes(k)),'INVALID_REQUEST',400);}
function deferred(error:string,status=409):Deferred{return {deferred_error:error,status};}
