 private async target(c:pg.PoolClient,a:Auth,id:string,round:string,normal=true){const l=await this.loaded(c,a.room.id,id);requireThat(l.row.id===round,'ROUND_STALE',409);await this.actor(c,l.game,round,a.member.id);const live=await this.reconcile(c,l);if(normal&&!(live&&l.game.state==='active'&&['pending','active'].includes(l.data.state)))l.denied=true;return l;}
